-- Produs nou: cafetieră espresso manuală portabilă (livrată prin Helpship; stoc 0 până ajunge marfa la depozit)
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, compare_at_price, cost_price, sku, stock, track_stock, weight_g, images, benefits, faq, bundles, badge, category, active, featured, sort)
VALUES ('cafetiera-espresso-manuala-portabila', 'Cafetieră espresso manuală portabilă', 'Espresso cu cremă oriunde ești, fără priză și fără baterii',
 'O cafetieră espresso de buzunar care funcționează fără curent și fără baterii. Pui cafea măcinată și apă fierbinte, apeși de câteva ori pistonul și ai un espresso aromat, cu cremă, în 10–15 secunde.

Este gândită pentru drum: birou, mașină, camping, tren sau hotel. Cântărește doar 245 g și are 20,5 × 8 × 6,5 cm, așa că încape în rucsac, în geanta de laptop sau în torpedou.

Pentru o ceașcă folosești aproximativ 8 g de cafea măcinată fin și apă fierbinte de 90–95°C, din fierbător sau dintr-un termos. Rezultă aproximativ 60 ml de espresso, cu gust intens.

Toate piesele se demontează ușor și se clătesc cu apă. Corpul e din plastic dur, cu componente din oțel inoxidabil, rezistent la folosirea zilnică și la drumuri.',
 8900, 0, 2400, 'CHI-ESP-01', 0, 1, 350,
 '["/img/cafetiera-espresso-1.jpg", "/img/cafetiera-espresso-2.jpg", "/img/cafetiera-espresso-3.jpg", "/img/cafetiera-espresso-4.jpg", "/img/cafetiera-espresso-5.jpg"]', '["Fără electricitate, funcționează prin presiune manuală", "Espresso cu cremă gata în 10–15 secunde", "Ușoară: doar 245 g, încape în rucsac sau torpedou", "Se demontează ușor, se curăță doar cu apă"]', '[{"q": "Am nevoie de curent sau de baterii?", "a": "Nu. Cafetiera funcționează doar prin presiune manuală: apeși pistonul, iar apa trece prin cafea. Ai nevoie doar de apă fierbinte, din fierbător sau dintr-un termos."}, {"q": "Ce cafea folosesc?", "a": "Cafea măcinată fin, pentru espresso, aproximativ 8 g pentru o ceașcă. O cafea măcinată prea grosier dă un espresso mai slab."}, {"q": "Încălzește singură apa?", "a": "Nu, apa se pune deja fierbinte, ideal la 90–95°C. Nu folosi apă care tocmai a clocotit, ca să nu ardă aroma cafelei."}, {"q": "Câtă cafea face o dată?", "a": "Aproximativ 60 ml de espresso la o umplere, adică o ceașcă. Ceașca este chiar capacul cafetierei."}, {"q": "Cum se curăță?", "a": "Desfaci piesele și le clătești cu apă curată, apoi le lași să se usuce. Se montează la loc în câteva secunde."}, {"q": "Cât durează livrarea?", "a": "24–48 de ore lucrătoare de la confirmarea comenzii. Plătești la livrare."}]', '[{"qty": 1, "pct": 0, "label": ""}, {"qty": 2, "pct": 10, "label": "Cel mai ales"}, {"qty": 3, "pct": 15, "label": "Cea mai bună ofertă"}]', 'Nou', 'Bucătărie', 1, 0, 1);
UPDATE products SET sections = '[{"title": "Espresso adevărat, fără priză", "image": "/img/cafetiera-espresso-2.jpg", "text": "Cafetiera funcționează doar prin presiune manuală. Apeși pistonul de pe lateral, iar apa fierbinte trece prin cafeaua măcinată și curge direct în ceașcă.\n\nÎn 10–15 secunde ai un espresso cu cremă, fără aparat mare, fără capsule și fără curent."}, {"title": "Cafeaua ta, oriunde ești", "image": "/img/cafetiera-espresso-3.jpg", "text": "La birou, în pauză. În mașină, la o oprire pe drum. La cort, dimineața. În tren sau în camera de hotel.\n\nAi nevoie doar de cafea măcinată și apă fierbinte, iar ceașca e chiar capacul cafetierei."}, {"title": "Gata în câțiva pași simpli", "image": "/img/cafetiera-espresso-5.jpg", "text": "Pui apa fierbinte în rezervor, cafeaua în filtru, asamblezi cafetiera și apeși butonul. Fără setări complicate și fără experiență de barista.\n\nPentru cel mai bun gust folosește cafea măcinată fin pentru espresso, aproximativ 8 g pentru o ceașcă."}, {"title": "Mică, solidă și ușor de curățat", "image": "/img/cafetiera-espresso-4.jpg", "text": "Are cinci piese care se demontează ușor: ceașca, capul de extracție, filtrul pentru cafea, pistonul și rezervorul de apă. După folosire le clătești cu apă și sunt gata pentru următoarea cafea.\n\nCorpul din plastic dur și componentele din oțel inoxidabil fac față drumurilor și folosirii de zi cu zi."}]', specs = '[{"k": "Tip", "v": "Cafetieră espresso manuală, portabilă"}, {"k": "Funcționare", "v": "Presiune manuală, fără electricitate sau baterii"}, {"k": "Timp de preparare", "v": "10–15 secunde"}, {"k": "Cantitate", "v": "Aproximativ 60 ml espresso (o ceașcă)"}, {"k": "Cafea recomandată", "v": "Măcinată fin pentru espresso, aproximativ 8 g"}, {"k": "Apă", "v": "Fierbinte, 90–95°C (preparată separat)"}, {"k": "Dimensiuni", "v": "20,5 × 8 × 6,5 cm"}, {"k": "Greutate", "v": "245 g"}, {"k": "Material", "v": "Plastic dur și componente din oțel inoxidabil"}, {"k": "Componente", "v": "Ceașcă, cap de extracție, filtru pentru cafea, piston, rezervor de apă"}]', fulfillment = 'helpship', length_cm = 22, width_cm = 10, height_cm = 8
WHERE slug = 'cafetiera-espresso-manuala-portabila';
